典型写法：
```cpp
class Counter {
public:
    void operator()() const
    {
        for (int i{0}; i < m_numIterations; ++i) {
            std::lock_guard lock{m_mutex};
            std::cout << "Counter " << m_id
                      << " has value " << i << std::endl;
        }
    }

private:
    int m_id;
    int m_numIterations;
    inline static std::mutex m_mutex;
};
```
